func makeNamedType(pkgPath, pkgName, typeName string) *types.Named {
	pkg := types.NewPackage(pkgPath, pkgName)
	name := types.NewTypeName(0, pkg, typeName, nil)
	return types.NewNamed(name, types.Typ[types.Int], nil)
}

func TestTypeMapBasicOperations(t *testing.T) {
	m := &TypeMap{}

	// Len of empty map.
	if l := m.Len(); l != 0 {
		t.Fatalf("Len() on empty TypeMap: got %d, want 0", l)
	}

	// At on empty map.
	if v := m.At(tInt); v != nil {
		t.Fatalf("At() on empty TypeMap: got %v, want nil", v)
	}

	// Delete on empty map.
	if m.Delete(tInt) {
		t.Fatal("Delete() on empty TypeMap: got true, want false")
	}

	// Set and retrieve basic types.
	if prev := m.Set(tInt, "int_val"); prev != nil {
		t.Fatalf("Set() on empty TypeMap returned non-nil previous value: %v", prev)
	}
	if prev := m.Set(tStr, "str_val"); prev != nil {
		t.Fatalf("Set() on empty TypeMap returned non-nil previous value: %v", prev)
	}

	if l := m.Len(); l != 2 {
		t.Fatalf("Len(): got %d, want 2", l)
	}
	if v := m.At(tInt); v != "int_val" {
		t.Fatalf("At(int): got %v, want int_val", v)
	}
	if v := m.At(tStr); v != "str_val" {
		t.Fatalf("At(string): got %v, want str_val", v)
	}

	// Overwrite existing key.
	if prev := m.Set(tInt, "int_val2"); prev != "int_val" {
		t.Fatalf("Set() overwrite: got prev %v, want int_val", prev)
	}
	if v := m.At(tInt); v != "int_val2" {
		t.Fatalf("At(int) after overwrite: got %v, want int_val2", v)
	}
	if l := m.Len(); l != 2 {
		t.Fatalf("Len() after overwrite: got %d, want 2", l)
	}

	// Delete existing key.
	if !m.Delete(tInt) {
		t.Fatal("Delete(int): got false, want true")
	}
	if l := m.Len(); l != 1 {
		t.Fatalf("Len() after delete: got %d, want 1", l)
	}
	if v := m.At(tInt); v != nil {
		t.Fatalf("At(int) after delete: got %v, want nil", v)
	}

	// Delete already-deleted key.
	if m.Delete(tInt) {
		t.Fatal("Delete(int) second time: got true, want false")
	}

	// Test with named types that are structurally identical but distinct.
	namedA := makeNamedType("test/pkg", "pkg", "A")
	namedB := makeNamedType("test/pkg", "pkg", "B")

	m.Set(namedA, "A")
	m.Set(namedB, "B")
	if v := m.At(namedA); v != "A" {
		t.Fatalf("At(namedA): got %v, want A", v)
	}
	if v := m.At(namedB); v != "B" {
		t.Fatalf("At(namedB): got %v, want B", v)
	}

	// Test Keys.
	keys := m.Keys()
	if len(keys) != m.Len() {
		t.Fatalf("Keys() length %d != Len() %d", len(keys), m.Len())
	}

	// Test Iterate.
	count := 0
	m.Iterate(func(key types.Type, value any) {
		count++
	})
	if count != m.Len() {
		t.Fatalf("Iterate count %d != Len() %d", count, m.Len())
	}
}

func TestTypeMapLoadOrStore(t *testing.T) {
	m := &TypeMap{}

	// First call should store and return (value, false).
	val, loaded := m.LoadOrStore(tInt, "first")
	if loaded {
		t.Fatal("LoadOrStore first call: got loaded=true, want false")
	}
	if val != "first" {
		t.Fatalf("LoadOrStore first call: got val=%v, want first", val)
	}

	// Second call with same key should return (existing, true).
	val, loaded = m.LoadOrStore(tInt, "second")
	if !loaded {
		t.Fatal("LoadOrStore second call: got loaded=false, want true")
	}
	if val != "first" {
		t.Fatalf("LoadOrStore second call: got val=%v, want first", val)
	}

	// Verify Len is 1 (not 2).
	if l := m.Len(); l != 1 {
		t.Fatalf("Len() after two LoadOrStore: got %d, want 1", l)
	}

	// LoadOrStore with a different key should store.
	val, loaded = m.LoadOrStore(tStr, "string_val")
	if loaded {
		t.Fatal("LoadOrStore different key: got loaded=true, want false")
	}
	if val != "string_val" {
		t.Fatalf("LoadOrStore different key: got val=%v, want string_val", val)
	}
	if l := m.Len(); l != 2 {
		t.Fatalf("Len() after three LoadOrStore: got %d, want 2", l)
	}

	// Verify At returns the stored values.
	if v := m.At(tInt); v != "first" {
		t.Fatalf("At(int): got %v, want first", v)
	}
	if v := m.At(tStr); v != "string_val" {
		t.Fatalf("At(string): got %v, want string_val", v)
	}
}

func TestTypeMapSetNoLock(t *testing.T) {
	m := &TypeMap{}

	// SetNoLock on empty map.
	if prev := m.SetNoLock(tInt, "val1"); prev != nil {
		t.Fatalf("SetNoLock() on empty: got prev %v, want nil", prev)
	}
	if v := m.At(tInt); v != "val1" {
		t.Fatalf("At() after SetNoLock: got %v, want val1", v)
	}
	if l := m.Len(); l != 1 {
		t.Fatalf("Len() after SetNoLock: got %d, want 1", l)
	}

	// SetNoLock overwrite.
	if prev := m.SetNoLock(tInt, "val2"); prev != "val1" {
		t.Fatalf("SetNoLock() overwrite: got prev %v, want val1", prev)
	}
	if v := m.At(tInt); v != "val2" {
		t.Fatalf("At() after SetNoLock overwrite: got %v, want val2", v)
	}
	if l := m.Len(); l != 1 {
		t.Fatalf("Len() after SetNoLock overwrite: got %d, want 1", l)
	}

	// SetNoLock with different key.
	if prev := m.SetNoLock(tStr, "str"); prev != nil {
		t.Fatalf("SetNoLock() new key: got prev %v, want nil", prev)
	}
	if l := m.Len(); l != 2 {
		t.Fatalf("Len() after second SetNoLock: got %d, want 2", l)
	}
}

func TestTypeMapNilReceiver(t *testing.T) {
	var m *TypeMap

	// None of these should panic.
	if v := m.At(tInt); v != nil {
		t.Fatalf("At() on nil TypeMap: got %v, want nil", v)
	}
	if l := m.Len(); l != 0 {
		t.Fatalf("Len() on nil TypeMap: got %d, want 0", l)
	}
	if m.Delete(tInt) {
		t.Fatal("Delete() on nil TypeMap: got true, want false")
	}

	// Iterate on nil should be a no-op.
	m.Iterate(func(key types.Type, value any) {
		t.Fatal("Iterate on nil TypeMap should not call the function")
	})

	// Keys on nil should return empty slice.
	keys := m.Keys()
	if len(keys) != 0 {
		t.Fatalf("Keys() on nil TypeMap: got %d keys, want 0", len(keys))
	}

	// String on nil should return "{}".
	if s := m.String(); s != "{}" {
		t.Fatalf("String() on nil TypeMap: got %q, want %q", s, "{}")
	}
}

func TestTypeMapConcurrentSet(t *testing.T) {
	m := &TypeMap{}
	const numGoroutines = 50
	const typesPerGoroutine = 20

	// Pre-create all types so we can reuse the same pointers for verification.
	// Named types are compared by identity (pointer), not structure.
	allTypes := make([][]*types.Named, numGoroutines)
	for g := 0; g < numGoroutines; g++ {
		allTypes[g] = make([]*types.Named, typesPerGoroutine)
		for i := 0; i < typesPerGoroutine; i++ {
			allTypes[g][i] = makeNamedType(
				fmt.Sprintf("test/pkg%d", g),
				fmt.Sprintf("pkg%d", g),
				fmt.Sprintf("T%d", i),
			)
		}
	}

	var wg sync.WaitGroup
	wg.Add(numGoroutines)

	for g := 0; g < numGoroutines; g++ {
		g := g
		go func() {
			defer wg.Done()
			for i := 0; i < typesPerGoroutine; i++ {
				m.Set(allTypes[g][i], fmt.Sprintf("g%d_t%d", g, i))
			}
		}()
	}
	wg.Wait()

	// All entries should be present.
	expectedLen := numGoroutines * typesPerGoroutine
	if l := m.Len(); l != expectedLen {
		t.Fatalf("Len() after concurrent Set: got %d, want %d", l, expectedLen)
	}

	// Verify each entry is retrievable using the same type pointers.
	for g := 0; g < numGoroutines; g++ {
		for i := 0; i < typesPerGoroutine; i++ {
			v := m.At(allTypes[g][i])
			if v == nil {
				t.Fatalf("At(g%d_T%d) returned nil", g, i)
			}
			expected := fmt.Sprintf("g%d_t%d", g, i)
			if v != expected {
				t.Fatalf("At(g%d_T%d): got %v, want %v", g, i, v, expected)
			}
		}
	}
}

func TestTypeMapConcurrentLoadOrStore(t *testing.T) {
	m := &TypeMap{}
	const numGoroutines = 100

	// All goroutines race to LoadOrStore the same key.
	sharedType := makeNamedType("test/shared", "shared", "S")

	var wg sync.WaitGroup
	wg.Add(numGoroutines)

	storedCount := make(chan int, numGoroutines)
	loadedCount := make(chan int, numGoroutines)

	for g := 0; g < numGoroutines; g++ {
		g := g
		go func() {
			defer wg.Done()
			val, loaded := m.LoadOrStore(sharedType, g)
			if loaded {
				loadedCount <- val.(int)
			} else {
				storedCount <- val.(int)
			}
		}()
	}
	wg.Wait()
	close(storedCount)
	close(loadedCount)

	// Exactly one goroutine should have stored.
	stored := 0
	var winnerVal int
	for v := range storedCount {
		stored++
		winnerVal = v
	}
	if stored != 1 {
		t.Fatalf("Expected exactly 1 store, got %d", stored)
	}

	// All loaded goroutines should have received the winner's value.
	loaded := 0
	for v := range loadedCount {
		loaded++
		if v != winnerVal {
			t.Fatalf("Loaded value %d != stored value %d", v, winnerVal)
		}
	}

	if stored+loaded != numGoroutines {
		t.Fatalf("stored(%d) + loaded(%d) != %d", stored, loaded, numGoroutines)
	}

	// Map should have exactly 1 entry.
	if l := m.Len(); l != 1 {
		t.Fatalf("Len() after concurrent LoadOrStore: got %d, want 1", l)
	}
}

