func TestTypeMapLoadOrStoreWriteLockPath(t *testing.T) {
	// Exercise the write-lock path: bucket exists but key is not present.
	m := &TypeMap{}

	// Store a key via Set to ensure the bucket exists.
	m.Set(tInt, "int_val")

	// LoadOrStore a different key — creates new entry via write-lock path.
	val, loaded := m.LoadOrStore(tPStr1, "pstr1_val")
	if loaded {
		t.Fatal("LoadOrStore should store new key, got loaded=true")
	}
	if val != "pstr1_val" {
		t.Fatalf("expected pstr1_val, got %v", val)
	}

	// LoadOrStore with tPStr2 (structurally identical to tPStr1).
	// Should find tPStr1's entry via the read-lock path.
	val, loaded = m.LoadOrStore(tPStr2, "pstr2_val")
	if !loaded {
		t.Fatal("LoadOrStore should load existing key, got loaded=false")
	}
	if val != "pstr1_val" {
		t.Fatalf("expected pstr1_val (original), got %v", val)
	}

	if m.Len() != 2 {
		t.Fatalf("expected 2 entries, got %d", m.Len())
	}
}

func TestTypeMapLoadOrStoreAfterDelete(t *testing.T) {
	// Exercise the hole-reuse path in LoadOrStore.
	m := &TypeMap{}

	m.Set(tInt, "int_val")
	m.Set(tStr, "str_val")

	// Delete one to create a hole.
	if !m.Delete(tStr) {
		t.Fatal("Delete should succeed")
	}
	if m.Len() != 1 {
		t.Fatalf("expected 1 after delete, got %d", m.Len())
	}

	// LoadOrStore with a new key.
	val, loaded := m.LoadOrStore(tChanInt1, "chan_val")
	if loaded {
		t.Fatal("LoadOrStore should store new key")
	}
	if val != "chan_val" {
		t.Fatalf("expected chan_val, got %v", val)
	}

	if v := m.At(tInt); v != "int_val" {
		t.Fatalf("At(int): got %v, want int_val", v)
	}
	if v := m.At(tChanInt1); v != "chan_val" {
		t.Fatalf("At(chan): got %v, want chan_val", v)
	}
}

