func TestTypeMapConcurrentLoadOrStoreWriteLockDoubleCheck(t *testing.T) {
	// Exercise write-lock double-check path (lines 190-198 of pmap.go):
	// Bucket exists with a different entry, N goroutines race to LoadOrStore
	// the same NEW key. The first goroutine adds it under write-lock; the rest
	// discover it during the double-check after acquiring the write-lock.
	m := &TypeMap{}
	targetKey := makeNamedType("test/wldc", "wldc", "Target")
	h := hash(targetKey)

	// Seed the bucket at targetKey's hash with an unrelated entry so
	// tbl.Load(h) succeeds (fast path), but targetKey is not found under RLock.
	dummyKey := makeNamedType("test/wldc", "wldc", "Dummy")
	m.getTable().Store(h, &bucket{entries: []entry{{key: dummyKey, value: "dummy"}}})
	m.length.Add(1)

	const N = 100
	var wg sync.WaitGroup
	wg.Add(N)
	start := make(chan struct{})

	results := make([]struct {
		val    any
		loaded bool
	}, N)

	for i := 0; i < N; i++ {
		i := i
		go func() {
			defer wg.Done()
			<-start
			val, loaded := m.LoadOrStore(targetKey, i)
			results[i] = struct {
				val    any
				loaded bool
			}{val, loaded}
		}()
	}
	close(start)
	wg.Wait()

	storedCount := 0
	var storedVal int
	for i := 0; i < N; i++ {
		if !results[i].loaded {
			storedCount++
			storedVal = results[i].val.(int)
		}
	}
	if storedCount != 1 {
		t.Fatalf("expected exactly 1 store, got %d", storedCount)
	}
	for i := 0; i < N; i++ {
		if results[i].loaded && results[i].val.(int) != storedVal {
			t.Fatalf("goroutine %d loaded %d, want %d", i, results[i].val, storedVal)
		}
	}
	// 2 entries: dummy + target
	if l := m.Len(); l != 2 {
		t.Fatalf("Len() = %d, want 2", l)
	}
}

func TestTypeMapConcurrentLoadOrStoreHoleReuse(t *testing.T) {
	// Exercise write-lock hole-reuse path (lines 202-214 of pmap.go):
	// Bucket exists with a hole (nil-key entry from a prior delete), N goroutines
	// race to LoadOrStore a new key. The winner should reuse the hole.
	m := &TypeMap{}
	targetKey := makeNamedType("test/hole", "hole", "Target")
	h := hash(targetKey)

	// Seed bucket with two entries, then nil-out one to create a hole.
	keepKey := makeNamedType("test/hole", "hole", "Keep")
	holeKey := makeNamedType("test/hole", "hole", "Hole")
	b := &bucket{entries: []entry{
		{key: holeKey, value: "to_delete"},
		{key: keepKey, value: "keep"},
	}}
	m.getTable().Store(h, b)
	m.length.Add(2)

	// Create hole by nil-ing the first entry (simulates Delete).
	b.entries[0] = entry{}
	m.length.Add(-1)

	const N = 100
	var wg sync.WaitGroup
	wg.Add(N)
	start := make(chan struct{})

	results := make([]struct {
		val    any
		loaded bool
	}, N)

	for i := 0; i < N; i++ {
		i := i
		go func() {
			defer wg.Done()
			<-start
			val, loaded := m.LoadOrStore(targetKey, i)
			results[i] = struct {
				val    any
				loaded bool
			}{val, loaded}
		}()
	}
	close(start)
	wg.Wait()

	storedCount := 0
	for i := 0; i < N; i++ {
		if !results[i].loaded {
			storedCount++
		}
	}
	if storedCount != 1 {
		t.Fatalf("expected exactly 1 store, got %d", storedCount)
	}
	// 2 entries: keepKey + targetKey (hole was reused)
	if l := m.Len(); l != 2 {
		t.Fatalf("Len() = %d, want 2", l)
	}
}

func TestTypeMapConcurrentLoadOrStoreDifferentKeys(t *testing.T) {
	// Exercise slow path (lines 220-243 of pmap.go) and fast path concurrently
	// with many different keys. Some goroutines create new buckets (slow path),
	// others find existing buckets from natural hash collisions (fast path write-lock).
	m := &TypeMap{}
	const N = 200

	keys := make([]types.Type, N)
	for i := 0; i < N; i++ {
		keys[i] = makeNamedType("test/diff", "diff", fmt.Sprintf("T%d", i))
	}

	var wg sync.WaitGroup
	wg.Add(N)
	start := make(chan struct{})

	for i := 0; i < N; i++ {
		i := i
		go func() {
			defer wg.Done()
			<-start
			val, loaded := m.LoadOrStore(keys[i], i)
			if loaded {
				t.Errorf("goroutine %d: expected store, got load of %v", i, val)
			}
			if val != i {
				t.Errorf("goroutine %d: expected %d, got %v", i, i, val)
			}
		}()
	}
	close(start)
	wg.Wait()

	if l := m.Len(); l != N {
		t.Fatalf("Len() = %d, want %d", l, N)
	}
	for i := 0; i < N; i++ {
		v := m.At(keys[i])
		if v != i {
			t.Fatalf("At(T%d) = %v, want %d", i, v, i)
		}
	}
}

func TestTypeMapConcurrentLoadOrStoreSlowPathRace(t *testing.T) {
	// Exercise slow path bucket-creation race (lines 222-238 of pmap.go)
	// with keys guaranteed to share the same hash. Multiple goroutines race
	// to LoadOrStore different keys that map to the same bucket.
	m := &TypeMap{}

	// Create unique keys and find a set that share the same hash.
	type keyInfo struct {
		typ  types.Type
		hash uint32
	}
	hashGroups := make(map[uint32][]types.Type)
	for i := 0; i < 500; i++ {
		k := makeNamedType("test/spr", "spr", fmt.Sprintf("K%d", i))
		h := hash(k)
		hashGroups[h] = append(hashGroups[h], k)
	}

	// Find the largest collision group.
	var collisionKeys []types.Type
	for _, keys := range hashGroups {
		if len(keys) > len(collisionKeys) {
			collisionKeys = keys
		}
	}

	if len(collisionKeys) < 2 {
		t.Skip("no hash collisions found among 500 types — cannot exercise slow path race with different keys")
	}

	N := len(collisionKeys)
	var wg sync.WaitGroup
	wg.Add(N)
	start := make(chan struct{})

	for i := 0; i < N; i++ {
		i := i
		go func() {
			defer wg.Done()
			<-start
			val, loaded := m.LoadOrStore(collisionKeys[i], i)
			if loaded {
				t.Errorf("goroutine %d: expected store, got load of %v", i, val)
			}
			if val != i {
				t.Errorf("goroutine %d: expected %d, got %v", i, i, val)
			}
		}()
	}
	close(start)
	wg.Wait()

	if l := m.Len(); l != N {
		t.Fatalf("Len() = %d, want %d", l, N)
	}
	for i := 0; i < N; i++ {
		v := m.At(collisionKeys[i])
		if v != i {
			t.Fatalf("At(collisionKeys[%d]) = %v, want %d", i, v, i)
		}
	}
}

